const functions = require("firebase-functions");
const admin = require("firebase-admin");

// Inicializamos la app de administración para tener permisos de "superusuario"
admin.initializeApp();

/**
 * Trigger: onCreatePlayer
 * Se dispara AUTOMÁTICAMENTE cuando se crea un documento nuevo 
 * en la colección "players" de Firestore.
 */
exports.onCreatePlayer = functions.firestore
    .document("players/{playerId}")
    .onCreate(async (snapshot, context) => {
        // 1. Obtenemos los datos del jugador recién creado
        const playerData = snapshot.data();

        // Si por alguna razón no hay datos, paramos.
        if (!playerData) {
            console.log("No se encontraron datos en el documento.");
            return;
        }

        // 2. Definimos el mensaje de la notificación
        // El 'topic' (tema) es "updates". Tu app móvil debe estar suscrita a este tema.
        const message = {
            notification: {
                title: "¡Nuevo Fichaje! ⚽",
                body: `${playerData.name} se ha unido al equipo como ${playerData.position}.`
            },
            topic: "updates"
        };

        // 3. Enviamos la notificación a la nube de Firebase (FCM)
        try {
            const response = await admin.messaging().send(message);
            console.log("Notificación enviada exitosamente:", response);
            return null; // Las Cloud Functions siempre deben retornar algo o una promesa
        } catch (error) {
            console.error("Error al enviar la notificación:", error);
            return null;
        }
    });